                    LOG.warn("SAXParser doesn't support the feature {} with value {}, due to {}.", new Object[] { "http://xml.org/sax/features/external-parameter-entities", "false", e });
                }
            }
            sfactory.setNamespaceAware(true);
            SAXParser parser = sfactory.newSAXParser();
            xmlReader = parser.getXMLReader();
            try {
                xmlReader.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            } catch (Exception e) {
                LOG.warn("SAXParser doesn't support the feature {} with value {}, due to {}.", new Object[] { "http://apache.org/xml/features/disallow-doctype-decl", "true", e });
